"""Where the admin panel lives (docs/ADMIN_ACCESS.md): a secret path, generated by the server, kept ONLY in the database.

This is one more layer of hiding on top of the real protection (the login and `require_admin` on every /admin route). Nothing here replaces them.

* `site_settings` (key, value): the key `admin_path` holds a random segment of 14 characters (a-z, 0-9). It is created ONCE (at startup, or on first
  use) and never changes unless the admin asks for a new one. It is never written in the code, the repository, the environment, the logs or an answer
  for anybody who is not the signed-in admin: GET /me/roles and GET /admin/access-path give it only to the admin.
* POST /route-check {"segment"}: {"match": true | false}. Constant-time comparison, a strict limit per address, ALWAYS answer 200 with the same shape
  (a limited caller gets {"match": false}): it only lets the admin's bookmark show the login before signing in.
* POST /admin/settings/admin-path/rotate: a new path, the old one stops working. The audit log gets the action and the abbreviated uid, never the value.
* The scan guard: more than SCAN_LIMIT answers "not found" to the same address in 5 minutes are answered 429 for 15 minutes. Only counts are kept.
"""
import hashlib
import hmac
import logging
import secrets
import string
import threading
import time

from fastapi import Depends, Request

import web_safety
from database import get_connection

logger = logging.getLogger("thundbalance.admin_access")

KEY = "admin_path"
LENGTH = 14
ALPHABET = string.ascii_lowercase + string.digits
SCAN_LIMIT = 30                     # "not found" answers per address ...
SCAN_WINDOW_SECONDS = 300           # ... in 5 minutes ...
BLOCK_SECONDS = 900                 # ... and then 15 minutes of 429
CHECK_LIMIT = web_safety.SharedRateLimit("route_check", 10, 60)
SCAN_HITS = web_safety.SharedRateLimit("scan_404", 10 ** 9, SCAN_WINDOW_SECONDS)        # only used to count (hit)
SCAN_BLOCKS = web_safety.SharedRateLimit("scan_block", 10 ** 9, BLOCK_SECONDS)          # one hit = this address is blocked
# the paths whose "not found" is a file that is simply not there: a broken image is not a scan
NOT_A_SCAN = ("/uploads/",)
# the "address" of Starlette's TestClient: never a real caller (a real one is an IP address), and the test suites make hundreds of "not found" on purpose
EXEMPT_ADDRESSES = {"testclient"}

_table_ready = False
_lock = threading.Lock()
_local_block = {}                   # address (hashed) -> monotonic time until which it is blocked, in this process
_local_clear = {}                   # address (hashed) -> monotonic time until which "not blocked" is trusted (saves a query per request)
CLEAR_TRUST_SECONDS = 5


def ensure_table():
    global _table_ready
    conn = get_connection()
    try:
        cursor = conn.cursor()
        cursor.execute("CREATE TABLE IF NOT EXISTS site_settings (key TEXT PRIMARY KEY, value TEXT, updated_at TIMESTAMP NOT NULL DEFAULT NOW())")
        conn.commit()
    finally:
        conn.close()
    _table_ready = True


def _generate():
    return "".join(secrets.choice(ALPHABET) for _ in range(LENGTH))


def ensure_admin_path():
    """Creates the path if there is none (idempotent: a second call, or another server starting at the same time, keeps the first). Returns it."""
    if not _table_ready:
        ensure_table()
    conn = get_connection()
    try:
        cursor = conn.cursor()
        cursor.execute("INSERT INTO site_settings (key, value) VALUES (%s, %s) ON CONFLICT (key) DO NOTHING", (KEY, _generate()))
        cursor.execute("SELECT value FROM site_settings WHERE key = %s", (KEY,))
        value = cursor.fetchone()[0]
        conn.commit()
        return value
    finally:
        conn.close()


def current_path():
    """The secret path (read from the database every time: a rotation is effective at once for every instance)."""
    return ensure_admin_path()


def rotate():
    """A new path; the previous one stops working at once. Returns the new one."""
    old = ensure_admin_path()
    new = _generate()
    while new == old:
        new = _generate()
    conn = get_connection()
    try:
        cursor = conn.cursor()
        cursor.execute("UPDATE site_settings SET value = %s, updated_at = NOW() WHERE key = %s", (new, KEY))
        conn.commit()
    finally:
        conn.close()
    return new


def matches(segment):
    """True when `segment` is the secret path. Constant time (hmac.compare_digest), and the database is read even for an empty segment."""
    wanted = current_path().encode("utf-8")
    given = segment.encode("utf-8", "ignore")[:64] if isinstance(segment, str) else b""
    return hmac.compare_digest(given, wanted)


def admin_url(path=""):
    """The full address of a page of the panel, for the e-mails to the team: <site>/<secret path><path>. The path is never logged."""
    from emails.template import site_url
    try:
        return f"{site_url()}/{current_path()}{path}"
    except Exception as error:  # noqa: BLE001 - an e-mail must still go out: it then links to the site, where the admin signs in as always
        logger.warning("admin link could not be built (%s)", type(error).__name__)
        return site_url()


# ----------------------------------------------------------------------------------------------------------------------------- the scan guard
def _key(ip):
    return hashlib.sha256(str(ip).encode("utf-8")).hexdigest()[:24]          # the address itself is not kept


def is_blocked(ip):
    """Has this address been answered with too many "not found"? Asks the database at most once every few seconds per address."""
    if ip in EXEMPT_ADDRESSES:
        return False
    key = _key(ip)
    now = time.monotonic()
    with _lock:
        if _local_block.get(key, 0) > now:
            return True
        if _local_clear.get(key, 0) > now:
            return False
    blocked = SCAN_BLOCKS.peek(key) > 0
    with _lock:
        if blocked:
            _local_block[key] = now + BLOCK_SECONDS
        else:
            _local_clear[key] = now + CLEAR_TRUST_SECONDS
        if len(_local_clear) > 5000:
            _local_clear.clear()
        if len(_local_block) > 5000:
            for stale in [name for name, until in _local_block.items() if until <= now]:
                _local_block.pop(stale, None)
    return blocked


def record_not_found(ip, path=""):
    """One more "not found" for this address. Returns True when it has just been blocked. Counts only; nothing is logged."""
    if ip in EXEMPT_ADDRESSES or str(path).startswith(NOT_A_SCAN):
        return False
    key = _key(ip)
    if SCAN_HITS.hit(key) > SCAN_LIMIT:
        if SCAN_BLOCKS.peek(key) == 0:
            SCAN_BLOCKS.hit(key)
            logger.info("scan guard: an address was blocked for %d minutes", BLOCK_SECONDS // 60)         # a count, never the address
        with _lock:
            _local_block[key] = time.monotonic() + BLOCK_SECONDS
        return True
    with _lock:
        _local_clear.pop(key, None)
    return False


def clear_guard():
    """Forgets every count and block (tests)."""
    SCAN_HITS.clear()
    SCAN_BLOCKS.clear()
    CHECK_LIMIT.clear()
    with _lock:
        _local_block.clear()
        _local_clear.clear()


# ----------------------------------------------------------------------------------------------------------------------------- routes
def register_admin_access_routes(app, require_admin):
    from client_lifecycle import audit
    admin = [Depends(require_admin)]

    @app.post("/route-check")
    async def route_check(request: Request):
        """{"match": true | false}: always 200 and always this shape (a limited address, a bad body, a wrong segment: the same {"match": false})."""
        try:
            body = await request.json()
        except Exception:  # noqa: BLE001
            body = None
        segment = body.get("segment") if isinstance(body, dict) else None
        limited = await _in_thread(CHECK_LIMIT.too_many, _key(web_safety.get_client_ip(request)))
        found = await _in_thread(matches, segment)
        return {"match": bool(found and not limited)}

    @app.get("/admin/access-path", dependencies=admin)
    def access_path():
        return {"admin_path": current_path()}

    @app.post("/admin/settings/admin-path/rotate")
    def rotate_path(claims=Depends(require_admin)):
        value = rotate()
        audit({"sub": str((claims or {}).get("sub") or "")[:8]}, "admin_path_rotate", None, "ok")        # the action and the abbreviated uid: never the value
        return {"admin_path": value}


async def _in_thread(function, *args):
    from starlette.concurrency import run_in_threadpool
    return await run_in_threadpool(function, *args)
